// OneLake mirroring: Eventhouse EH_Wildfire
// Mirrors every table to OneLake as Delta/Parquet with a 5-minute target latency,
// so Spark, the SQL endpoint and the ontology can read Eventhouse data without a copy.
// Applied 2026-09-05. Re-run safe: .alter-merge only changes the fields supplied.

// ---------- enable mirroring ----------
.alter-merge table bronze_fire_raw policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)
.alter-merge table bronze_weather_raw policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)
.alter-merge table bronze_aircraft_raw policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)
.alter-merge table ref_communes policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)
.alter-merge table ref_fire_stations policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)
.alter-merge table ref_water_bodies policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)
.alter-merge table ref_critical_infra policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)
.alter-merge table ref_ground_units policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)
.alter-merge table ref_gdacs_alerts policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)
.alter-merge table silver_fire_detections policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)
.alter-merge table silver_weather policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)
.alter-merge table silver_aircraft policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5)

// ---------- verify ----------
.show table * policy mirroring
| project EntityName, Policy
| extend p = parse_json(Policy)
| project EntityName,
          IsEnabled  = tobool(p.IsEnabled),
          Format     = tostring(p.Format),
          LatencyMin = toint(p.TargetLatencyInMinutes)
| sort by EntityName asc

